export function localizedCorpus() {
  return localizedCases.flatMap((c) => {
    const header = "header" in c ? c.header : "Year ended 31 March 2025";
    const rows: string[][] = [[c.title], [c.unit], ["", c.note, header]];
    if ("below" in c) rows.push(["", "", c.below]);
    c.labels.forEach((label, i) => rows.push([label, String(i + 71), c.amounts[i]!]));
    const basic = {
      ...c,
      fileName: `${c.id}.${c.format}`,
      bytes: encodeGrid(rows, c.format, "Report"),
    };
    // Real text-layer PDFs with an embedded Unicode TrueType font, generated by the adjacent script.
    return [
      basic,
      ...(["fr-sa-income", "de-gmbh-income", "es-sl-income"].includes(c.id)
        ? [
            {
              ...c,
              id: `${c.id}-pdf`,
              fileName: `${c.id}.pdf`,
              bytes: readFileSync(new URL(`./localized/${c.id}.pdf`, import.meta.url)),
            },
          ]
        : []),
    ];
  });
}
